import {disclaimer,categories,assetClasses,sampleTransactions,sampleBudgets,sampleAssets,parseDecimal,validDate,validateTransaction,analyzeFinance,analyzePortfolio,sampleBook,placeLimit,cancelOrder,bookLevels,learningReply} from "./assets/engine.js";
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])),icon=name=>`<svg aria-hidden="true"><use href="./assets/icons.svg#${name}"></use></svg>`,money=cents=>new Intl.NumberFormat("en-US",{style:"currency",currency:"USD"}).format(cents/100);
const tabNames=["cashflow","portfolio","book","notes"],colors=["#b7c881","#718c57","#d5bf92","#8d9f9e","#a98c86","#b9b2cb"],dialog=$("#dialog");
let transactions=structuredClone(sampleTransactions),budgets=structuredClone(sampleBudgets),assets=structuredClone(sampleAssets),book=sampleBook(),month="2026-11",tab="cashflow",messages=[],opener=null,openerData=null,toastTimer=0;
for(const name of tabNames.slice(1)){const panel=document.createElement("div");panel.className="lab-panel";panel.id=`lab-${name}`;panel.setAttribute("role","tabpanel");panel.setAttribute("aria-labelledby",`tab-${name}`);panel.hidden=true;$(".lab-bottom").before(panel);}
function toast(message){clearTimeout(toastTimer);$("#toast").textContent=message;$("#toast").hidden=false;toastTimer=setTimeout(()=>$("#toast").hidden=true,3500);}
function downloadSnapshot(){const data={version:1,disclaimer,selectedMonth:month,transactions,budgets,assets,portfolioAnalysis:analyzePortfolio(assets),orderBook:book};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+"\n"],{type:"application/json"})),a=document.createElement("a");a.href=url;a.download="folio-local-lab-snapshot.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderHero(){
  const f=analyzeFinance(transactions,month),weeks=Array.from({length:4},()=>({income:0,expense:0}));
  for(const entry of transactions.filter(t=>t.date.slice(0,7)===month))weeks[Math.min(3,Math.floor((Number(entry.date.slice(8))-1)/7))][entry.type]+=entry.amountCents;
  const max=Math.max(1,...weeks.flatMap(w=>[w.income,w.expense]));
  $("#hero-month").textContent=month+" / LOCAL INPUTS";$("#hero-net").textContent=money(f.savingsCents);$("#hero-rate").textContent=f.savingsRate===null?"Savings rate unavailable without income":(f.savingsRate*100).toFixed(1)+"% savings rate";
  $("#hero-income").textContent=money(f.incomeCents);$("#hero-expenses").textContent=money(f.expenseCents);
  $("#hero-chart").setAttribute("aria-label",`${month} weekly income and expenses: ${weeks.map((w,i)=>`group ${i+1}, income ${money(w.income)}, expenses ${money(w.expense)}`).join("; ")}`);
  $("#hero-chart").innerHTML=weeks.map((w,i)=>`<div class="hero-week"><i style="--h:${Math.round(w.income/max*112)}px"></i><i class="expense" style="--h:${Math.round(w.expense/max*112)}px"></i><span>${["01–07","08–14","15–21","22–END"][i]}</span></div>`).join("");
}
function renderCashflow(panel){
  const f=analyzeFinance(transactions,month),target=budgets[month]||{},selected=transactions.filter(t=>t.date.slice(0,7)===month).sort((a,b)=>a.date.localeCompare(b.date));
  panel.innerHTML=`<div class="lab-heading"><div><h3>Your numbers. In perspective.</h3><p>Manual sample transactions · exact cents · no bank connection</p></div><div class="lab-actions"><input id="selected-month" type="month" value="${month}" min="2020-01" max="2100-12" aria-label="Analysis month"><button class="button" data-action="transaction">Add transaction ${icon("plus")}</button></div></div><div class="metrics"><article class="metric"><small>ENTERED INCOME</small><strong id="finance-income">${money(f.incomeCents)}</strong><span>Selected month only</span></article><article class="metric"><small>ENTERED EXPENSES</small><strong id="finance-expenses">${money(f.expenseCents)}</strong><span>Selected month only</span></article><article class="metric"><small>NET FLOW</small><strong id="finance-net">${money(f.savingsCents)}</strong><span>${f.savingsRate===null?"No income; rate unavailable":(f.savingsRate*100).toFixed(1)+"% savings rate"}</span></article><article class="metric"><small>ILLUSTRATIVE HEALTH SCORE</small><strong id="finance-score">${f.score===null?"N/A":f.score+" / 100"}</strong><span>Disclosed heuristic, not advice</span></article></div><div class="lab-grid"><div><div class="subheading"><span>Entered transactions</span><span>${selected.length} in view</span></div><div class="transaction-list">${selected.length?selected.map(t=>`<article class="transaction-row"><span class="tx-icon">${icon(t.type==="income"?"arrow-down-left":"arrow-up-right")}</span><div><h4>${esc(t.name)}</h4><p>${t.date} / ${t.category}</p></div><strong class="${t.type}">${t.type==="income"?"+":"−"}${money(t.amountCents)}</strong><button data-action="transaction" data-id="${t.id}" aria-label="Edit ${esc(t.name)}">${icon("pencil")}</button></article>`).join(""):`<p class="empty">No transactions in this month. Add a manual entry to explore the calculations.</p>`}</div></div><div><div class="subheading"><span>Actual vs. monthly targets</span><button data-action="budget">Edit targets</button></div>${categories.map(c=>{const amount=f.byCategory[c],limit=target[c],over=limit&&amount>limit;return`<article class="budget-row ${over?"over":""}" data-budget-category="${c}"><div><strong>${c}</strong><small>${money(amount)} / ${limit?money(limit):"not set"}</small></div><div class="budget-track" aria-label="${c}: ${money(amount)} actual, ${limit?money(limit)+" target":"target not set"}"><i style="width:${limit?Math.min(100,amount/limit*100):0}%"></i></div></article>`;}).join("")}</div></div><p class="lab-note">The score is an educational formula, not a financial assessment. Fixed categories here are Housing and Utilities. Targets are separate for each selected month. <button data-action="method">Inspect the exact formula.</button></p>`;
  $("#selected-month").addEventListener("change",e=>{if(validDate(e.target.value+"-01")){month=e.target.value;render();}});
}
function renderPortfolio(panel){
  const a=analyzePortfolio(assets);let end=0;
  const gradient=assets.map((asset,i)=>{const start=end;end+=asset.weightBps/100;return `${colors[i%colors.length]} ${start}% ${end}%`;}).join(",");
  panel.innerHTML=`<div class="lab-heading"><div><h3>An allocation is a set of assumptions.</h3><p>Manual asset labels · no market prices or return estimates</p></div><div class="lab-actions"><button class="button" data-action="asset">Add asset label ${icon("plus")}</button></div></div>${a.valid?"":`<div class="warning" id="allocation-warning">Entered weights total ${(a.totalBps/100).toFixed(2)}%. Set exactly 100.00% to calculate the illustrative index and label-level concentration. No automatic normalization is applied.</div>`}<div class="allocation-grid"><div class="donut-area"><div class="donut" role="img" aria-label="${a.valid?"Entered allocation by asset label":"Allocation incomplete; no chart calculated"}" ${a.valid?`style="background:conic-gradient(${gradient})"`:""}><div class="donut-center"><strong id="allocation-total">${(a.totalBps/100).toFixed(2)}%</strong><span>${a.valid?"ENTERED ALLOCATION":"NOT CALCULATED"}</span></div></div><div class="allocation-stats"><div><strong id="class-index">${a.index===null?"—":a.index+" / 100"}</strong><small>ILLUSTRATIVE CLASS INDEX</small></div><div><strong id="concentration">${a.hhi===null?"—":a.hhi}</strong><small>LABEL HHI / 10000</small></div></div></div><div><div class="subheading"><span>Asset labels & weights</span><span>${assets.length} labels</span></div>${assets.length?assets.map((asset,i)=>`<article class="asset-row"><span class="asset-dot" style="background:${colors[i%colors.length]}"></span><div><h4>${esc(asset.name)}</h4><p>${asset.assetClass} · heuristic multiplier ${assetClasses[asset.assetClass]}</p></div><strong>${(asset.weightBps/100).toFixed(2)}%</strong><button data-action="asset" data-id="${asset.id}" aria-label="Edit ${esc(asset.name)}">${icon("pencil")}</button></article>`).join(""):`<p class="empty">Add asset labels and weights to begin.</p>`}</div></div><p class="lab-note">Cash=1, Bonds=2, Equities=4, Alternatives=5. Index = weighted mean multiplier ÷ 5 × 100. HHI = sum of squared label percentages (0–10000). Both require exactly 100%. These do not measure market volatility, underlying overlap, sector concentration, returns or suitability. <button data-action="method">Read the limitations.</button></p>`;
}
function renderBook(panel,message=""){
  const levels=bookLevels(book),max=Math.max(1,...levels.bids.map(x=>x.quantity),...levels.asks.map(x=>x.quantity));
  const side=(name,rows)=>`<div class="book-side ${name==="Asks"?"asks":""}"><h4>${name}<small>PRICE / QTY</small></h4>${rows.length?rows.map(level=>`<div class="level" style="--depth:${level.quantity/max*100}%"><span>${money(level.priceCents)}</span><span>${level.quantity}</span></div>`).join(""):`<p class="empty">No resting ${name.toLowerCase()}.</p>`}</div>`;
  panel.innerHTML=`<div class="lab-heading"><div><h3>One book. A very real algorithm.</h3><p>LAB / USD · fictional instrument · local simulation only</p></div><div class="lab-actions"><button class="text-button" data-action="reset-book">Reset sample book ${icon("rotate-ccw")}</button></div></div><div class="warning">No real orders, money, positions, fees or settlement. Both sides are seeded or locally entered; no anti-self-trade controls. Price–time matching is functional.</div><div class="book-grid"><form class="order-form" id="order-form"><label>Side<select name="side"><option value="buy">Buy</option><option value="sell">Sell</option></select></label><label>Limit price (sample USD)<input id="book-price" name="price" required inputmode="decimal" value="100.00"></label><label>Quantity (whole units)<input name="quantity" required type="number" min="1" max="10000" step="1" value="1"></label><button class="button">Simulate limit order ${icon("arrow-right")}</button><p class="lab-note">Better prices first, then sequence. Resting orders set fill prices. Price $0.01–$1,000,000; quantity 1–10,000. Limit: 200 orders per reset.</p><p class="status-message" id="order-message" role="status">${esc(message)}</p></form><div><div class="subheading"><span>Resting depth</span><span>Aggregate by price</span></div><div class="book-columns">${side("Bids",levels.bids)}${side("Asks",levels.asks)}</div><p class="spread">Best spread: <strong id="book-spread">${levels.spreadCents===null?"N/A · one or both sides empty":money(levels.spreadCents)}</strong></p></div><div><div class="subheading"><span>Simulated fills</span><span>${book.trades.length} fills</span></div><div class="book-history">${book.trades.length?`<table class="compact-table"><thead><tr><th>ID</th><th>Price</th><th>Qty</th><th>Resting order</th></tr></thead><tbody>${book.trades.map(t=>`<tr><td>${t.id}</td><td>${money(t.priceCents)}</td><td>${t.quantity}</td><td>${book.orders.find(o=>o.id===t.buyOrderId).sequence<book.orders.find(o=>o.id===t.sellOrderId).sequence?t.buyOrderId:t.sellOrderId}</td></tr>`).join("")}</tbody></table>`:`<p class="empty">No fills yet. Try buying 25 units at $101.00 to cross three seeded orders.</p>`}</div></div></div><details class="order-history"><summary>Order audit trail · ${book.orders.length} orders</summary><div class="table-scroll"><table class="compact-table"><thead><tr><th>ID / priority</th><th>Side</th><th>Limit</th><th>Original</th><th>Remaining</th><th>Status</th><th>Action</th></tr></thead><tbody>${book.orders.map(o=>`<tr><td>${o.id} / ${o.sequence}</td><td>${o.side}</td><td>${money(o.priceCents)}</td><td>${o.quantity}</td><td>${o.remaining}</td><td>${o.status}</td><td>${["open","partial"].includes(o.status)?`<button data-action="cancel-order" data-id="${o.id}" aria-label="Cancel ${o.id}">Cancel</button>`:"—"}</td></tr>`).join("")}</tbody></table></div></details><p class="lab-note">Timestamps in downloaded snapshots use this browser's clock. Strictly increasing sequence breaks ties; seeded orders are initialized locally, not historical exchange data.</p>`;
  $("#order-form").addEventListener("submit",e=>{e.preventDefault();const form=new FormData(e.target);try{const order=placeLimit(book,{side:form.get("side"),priceCents:parseDecimal(form.get("price")),quantity:Number(form.get("quantity"))});renderBook(panel,`${order.id} ${order.status}: ${order.quantity-order.remaining} of ${order.quantity} units filled locally. Nothing was sent.`);}catch(error){$("#order-message").textContent=error.message;$("#order-message").classList.add("error");}});
}
function renderNotes(panel){
  panel.innerHTML=`<div class="lab-heading"><div><h3>A local explainer, not an AI adviser.</h3><p>Deterministic rules · no LLM, prompt upload or model endpoint</p></div></div><div class="notes-layout"><aside class="note-context"><h4>Ask about the moving parts.</h4><p>Answers describe current ${month} cash flow, entered weights or this tab's order book. Each answer is a snapshot at the time you ask, not a live forecast.</p><div class="quick-notes"><button data-question="Explain my spending">Explain the cash flow</button><button data-question="Explain portfolio concentration">Unpack allocation concentration</button><button data-question="Explain the order book spread">Explain matching & the spread</button></div><p class="lab-note">A production LLM integration is not connected. No credentials or API keys are requested.</p></aside><div><div class="chat-history" aria-live="polite">${messages.length?messages.map(m=>`<article class="chat-message"><small>LOCAL RULES / SNAPSHOT ${m.month}</small><h4>${esc(m.question)}</h4><p>${esc(m.answer)}</p></article>`).join(""):`<p class="empty">Start with a topic on the left, or ask about spending, portfolio allocation, or the order book. This is a fixed-topic educational explainer.</p>`}</div><form class="chat-form" id="notes-form"><input name="question" maxlength="300" required aria-label="Question for the local rules explainer" placeholder="What can these numbers tell me?"><button class="button">Ask locally ${icon("arrow-right")}</button></form><p class="lab-note">${disclaimer} Ten most recent messages remain in memory; no chat history is included in snapshots.</p></div></div>`;
  const ask=question=>{if(!question.trim())return;messages.push({month,question:question.trim().slice(0,300),answer:learningReply(question,analyzeFinance(transactions,month),analyzePortfolio(assets),book)});messages=messages.slice(-10);renderNotes(panel);$(".chat-history").scrollTop=$(".chat-history").scrollHeight;$("#notes-form input").focus({preventScroll:true});};
  $("#notes-form").addEventListener("submit",e=>{e.preventDefault();ask(new FormData(e.target).get("question"));});document.querySelectorAll("[data-question]").forEach(b=>b.addEventListener("click",()=>ask(b.dataset.question)));
}
function render(){
  renderHero();
  for(const name of tabNames){const button=$(`#tab-${name}`),panel=$(`#lab-${name}`);button.setAttribute("aria-selected",String(name===tab));button.tabIndex=name===tab?0:-1;panel.hidden=name!==tab;if(name!==tab)panel.replaceChildren();}
  const panel=$(`#lab-${tab}`);
  if(tab==="cashflow")renderCashflow(panel);else if(tab==="portfolio")renderPortfolio(panel);else if(tab==="book")renderBook(panel);else renderNotes(panel);
}
function switchTab(name,focus=false){tab=name;render();history.pushState(null,"",`#lab-${name}`);if(focus)$(`#tab-${name}`).focus({preventScroll:true});}
function mount(title,body){if(!dialog.open){opener=document.activeElement;openerData=opener?.dataset?{...opener.dataset}:null;dialog.showModal();}$("#dialog-body").innerHTML=`<h2 id="dialog-title">${title}</h2>${body}`;dialog.scrollTop=0;$("#close-dialog").focus({preventScroll:true});}
function closeDialog(){dialog.close();$("#dialog-body").replaceChildren();const fallback=openerData?.action?document.querySelector(`[data-action="${openerData.action}"]${openerData.id?`[data-id="${openerData.id}"]`:""}`):null;(opener?.isConnected?opener:fallback||$(`#tab-${tab}`))?.focus({preventScroll:true});}
const field=(label,name,value,extra="")=>`<label>${label}<input name="${name}" value="${esc(value)}" required ${extra}></label>`;
function transactionForm(id){
  const existing=transactions.find(t=>t.id===id),t=existing||{name:"",type:"expense",category:"Other",date:month+"-01",amountCents:0};
  mount(existing?"Edit a manual entry.":"Add a manual entry.",`<p class="dialog-note">This changes local calculations, not a bank account. Every value is per transaction, with no automatic recurrence.</p><form id="transaction-form"><div class="form-grid">${field("Entry name","name",t.name,'maxlength="70"')}<label>Type<select name="type"><option value="income" ${t.type==="income"?"selected":""}>Income</option><option value="expense" ${t.type==="expense"?"selected":""}>Expense</option></select></label>${field("Amount (USD)","amount",(t.amountCents/100).toFixed(2),'inputmode="decimal"')}${field("Date","date",t.date,'type="date" min="2020-01-01" max="2100-12-31"')}<label class="wide">Expense category (income is labeled automatically)<select name="category">${categories.map(c=>`<option ${c===t.category?"selected":""}>${c}</option>`).join("")}</select></label></div><p class="form-error" id="form-error" role="status"></p><div class="form-actions"><button class="button">Save entry</button>${existing?`<button type="button" class="button outline" data-action="delete-transaction" data-id="${id}">Delete entry</button>`:""}<button type="button" class="quiet" data-action="close">Cancel</button></div></form>`);
  $("#transaction-form").addEventListener("submit",e=>{e.preventDefault();const f=new FormData(e.target);try{if(!existing&&transactions.length>=200)throw Error("Limit: 200 local transactions.");const entry={id:existing?.id||crypto.randomUUID(),name:f.get("name").trim(),type:f.get("type"),category:f.get("type")==="income"?"Income":f.get("category"),date:f.get("date"),amountCents:parseDecimal(f.get("amount"))};validateTransaction(entry);if(existing)transactions=transactions.map(x=>x.id===id?entry:x);else transactions.push(entry);render();closeDialog();toast("Manual entry updated locally.");}catch(error){$("#form-error").textContent=error.message;}});
}
function assetForm(id){
  const existing=assets.find(a=>a.id===id),asset=existing||{name:"",weightBps:0,assetClass:"Equities"};
  mount(existing?"Edit an asset label.":"Add an asset label.",`<p class="dialog-note">Use manual labels and weights, not live holdings. Intermediate totals may differ from 100%; the index stays unavailable until weights sum exactly to 100.00%.</p><form id="asset-form"><div class="form-grid">${field("Asset label","name",asset.name,'maxlength="50"')}${field("Weight (%)","weight",(asset.weightBps/100).toFixed(2),'inputmode="decimal"')}<label class="wide">Illustrative class<select name="assetClass">${Object.keys(assetClasses).map(c=>`<option ${c===asset.assetClass?"selected":""}>${c}</option>`).join("")}</select></label></div><p class="form-error" id="form-error" role="status"></p><div class="form-actions"><button class="button">Save asset label</button>${existing?`<button type="button" class="button outline" data-action="delete-asset" data-id="${id}">Remove label</button>`:""}<button type="button" class="quiet" data-action="close">Cancel</button></div></form>`);
  $("#asset-form").addEventListener("submit",e=>{e.preventDefault();const f=new FormData(e.target);try{const name=f.get("name").trim();if(!name||name.length>50)throw Error("Use a label of 1–50 characters.");if(assets.some(a=>a.id!==id&&a.name.toLowerCase()===name.toLowerCase()))throw Error("This asset label already exists.");if(!existing&&assets.length>=20)throw Error("Limit: twenty local labels.");const entry={id:existing?.id||crypto.randomUUID(),name,weightBps:parseDecimal(f.get("weight"),10000),assetClass:f.get("assetClass")};if(!Object.hasOwn(assetClasses,entry.assetClass))throw Error("Choose a supported illustrative asset class.");if(existing)assets=assets.map(a=>a.id===id?entry:a);else assets.push(entry);render();closeDialog();toast("Allocation inputs updated; no trades were placed.");}catch(error){$("#form-error").textContent=error.message;}});
}
function budgetForm(){
  const target=budgets[month]||{};
  mount(`Targets for ${month}.`,`<p class="dialog-note">Category targets are manual planning inputs for this selected month only. Empty fields remove a target; actual spending remains unchanged.</p><form id="budget-form"><div class="form-grid">${categories.map(c=>`<label>${c} target (USD)<input name="${c}" value="${target[c]?(target[c]/100).toFixed(2):""}" inputmode="decimal"></label>`).join("")}</div><p class="form-error" id="form-error" role="status"></p><div class="form-actions"><button class="button">Update monthly targets</button><button type="button" class="quiet" data-action="close">Cancel</button></div></form>`);
  $("#budget-form").addEventListener("submit",e=>{e.preventDefault();const f=new FormData(e.target);try{const next={};for(const c of categories)if(f.get(c).trim())next[c]=parseDecimal(f.get(c));budgets[month]=next;render();closeDialog();toast("This month's targets updated.");}catch(error){$("#form-error").textContent=error.message;}});
}
function method(){
  mount("Open the black box.",`<p class="dialog-note">${disclaimer} All starting figures and labels are illustrative, not verified account or market data.</p><ul class="method-list"><li>Finance: selected-month income and expenses sum integer cents. Savings rate = (income − expenses) / income. With no income, rate and score are unavailable. Housing and Utilities are the model's fixed categories.</li><li>Illustrative health score = round(70 × clamp(savings rate / 0.20, 0, 1) + 30 × clamp((1 − fixed expenses / income) / 0.50, 0, 1)). Thresholds are arbitrary teaching choices, not recommended spending ranges or a validated assessment.</li><li>Allocation uses integer basis points and requires exactly 100.00%. Illustrative multipliers: Cash 1, Bonds 2, Equities 4, Alternatives 5. Index = weighted mean multiplier / 5 × 100. No volatility or price history is measured.</li><li>Label-level HHI = sum of squared percentage weights (0–10000). It cannot reveal real sector overlap, correlated assets or underlying funds. Asset classes and names are manually entered.</li><li>Buy orders cross the lowest eligible asks; sell orders cross the highest eligible bids. Equal prices use lower arrival sequence first. Every fill uses the resting order's limit price. Remaining quantities rest; cancellation prevents future fills but preserves the audit trail.</li><li>LAB/USD is fictional. Both sides are local; no funding, holdings, fees, short-sale checks, exchange, settlement or anti-self-trade controls. Browser-clock timestamps are informational; sequence controls matching.</li><li>Learning notes are deterministic topic rules, not an AI/LLM integration. Responses are snapshots of current local numbers and always include the educational disclaimer.</li><li>Independent HTML/CSS/JavaScript static homepage. No Next.js, FastAPI, PostgreSQL, Docker, authentication or external AI service is connected. State is memory-only; downloaded snapshots contain inputs but exclude chat history. No environment variables are required.</li></ul>`);
}
document.addEventListener("click",e=>{
  const b=e.target.closest("[data-action]");if(!b)return;const {action,id}=b.dataset;
  if(action==="method")method();
  else if(action==="transaction")transactionForm(id);
  else if(action==="asset")assetForm(id);
  else if(action==="budget")budgetForm();
  else if(action==="close")closeDialog();
  else if(action==="snapshot")downloadSnapshot();
  else if(action==="cancel-order"){if(cancelOrder(book,id)){render();toast(`${id} canceled locally; previous fills retained.`);}}
  else if(action==="reset"||action==="reset-book")mount("Reset the local sample?",`<p class="dialog-note">${action==="reset"?"All transactions, budgets, allocations, orders, fills and learning messages":"The order book and its fills"} will be replaced by the original illustrative sample. Download a snapshot first if needed.</p><div class="form-actions"><button class="button" data-action="${action==="reset"?"confirm-reset":"confirm-reset-book"}">Replace sample data</button><button class="button outline" data-action="close">Keep current data</button></div>`);
  else if(action==="confirm-reset"||action==="confirm-reset-book"){if(action==="confirm-reset"){transactions=structuredClone(sampleTransactions);budgets=structuredClone(sampleBudgets);assets=structuredClone(sampleAssets);month="2026-11";messages=[];}book=sampleBook();render();closeDialog();toast("Illustrative sample restored.");}
  else if(action==="delete-transaction"||action==="delete-asset"){const isTransaction=action==="delete-transaction",entry=(isTransaction?transactions:assets).find(x=>x.id===id);mount("Remove this local entry?",`<p class="dialog-note">${esc(entry.name)} will be removed from local calculations only. No account or investment is affected.</p><div class="form-actions"><button class="button danger" data-action="${isTransaction?"confirm-delete-transaction":"confirm-delete-asset"}" data-id="${id}">Remove entry</button><button class="button outline" data-action="close">Keep entry</button></div>`);}
  else if(action==="confirm-delete-transaction"){transactions=transactions.filter(t=>t.id!==id);render();closeDialog();toast("Manual transaction removed.");}
  else if(action==="confirm-delete-asset"){assets=assets.filter(a=>a.id!==id);render();closeDialog();toast("Asset label removed; allocation recalculated.");}
});
$(".tabs").addEventListener("click",e=>{const b=e.target.closest("[data-tab]");if(b)switchTab(b.dataset.tab,true);});
$(".tabs").addEventListener("keydown",e=>{if(!["ArrowLeft","ArrowRight","Home","End"].includes(e.key))return;e.preventDefault();const index=tabNames.indexOf(tab),next=e.key==="Home"?0:e.key==="End"?tabNames.length-1:(index+(e.key==="ArrowRight"?1:-1)+tabNames.length)%tabNames.length;switchTab(tabNames[next],true);});
function restoreHash(){const name=location.hash.replace("#lab-","");if(tabNames.includes(name)){tab=name;render();$("#lab").scrollIntoView();}}
window.addEventListener("hashchange",restoreHash);
$("#close-dialog").addEventListener("click",closeDialog);dialog.addEventListener("cancel",e=>{e.preventDefault();closeDialog();});
$(".mobile-toggle").addEventListener("click",()=>{const open=!$("#navigation").classList.contains("open");$("#navigation").classList.toggle("open",open);$(".mobile-toggle").setAttribute("aria-expanded",String(open));});
$("#navigation").addEventListener("click",e=>{if(e.target.closest("a")){$("#navigation").classList.remove("open");$(".mobile-toggle").setAttribute("aria-expanded","false");}});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&$("#navigation").classList.contains("open")){$(".mobile-toggle").click();$(".mobile-toggle").focus();}});
render();restoreHash();
